{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Secondary attack rates were computed from raw data in each study, dividing the number of infected contacts of primary cases by the total number of susceptible exposed contacts. ... Secondary attack rates are presented as a proportion along with 95% CIs in forest plots.",
      "reason": "The manuscript specifies that the effect measure used for the primary outcome (secondary attack rate) is a proportion, calculated as the number of infected contacts divided by the total number of susceptible exposed contacts."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Heterogeneity between study estimates was gauged by means of the Cochran's Q and I 2 statistic: an I 2 value above 75% indicates high heterogeneity [16]. Moreover, a 95% prediction interval is displayed in the forest plots, which is an index of dispersion, providing information on how widely the true effect size varies.",
      "reason": "The authors report the use of I^2 statistics with a specific threshold (>75%) to interpret heterogeneity, and mention the use of prediction intervals to interpret the dispersion of effect sizes."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "The Freeman e Tukey double-arcsine variancestabilizing transformation was used to combine data, because of its advantage over log and logit transformations, which do not allow computation of the proportion in the presence of zero event counts [15].",
      "reason": "The authors describe the use of the Freeman-Tukey double-arcsine transformation as a method to re-express/transform the data for synthesis."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "The Freeman e Tukey double-arcsine variancestabilizing transformation was used to combine data, because of its advantage over log and logit transformations, which do not allow computation of the proportion in the presence of zero event counts [15].",
      "reason": "The choice of the Freeman-Tukey transformation is justified by its ability to handle zero event counts, which log/logit transformations cannot."
    }
  ],
  "confidence": 100
}

